\label{theorem: cohom / kummer / galois-to-milnor}
  The following hold:
  \begin{enumerate}
    \item Let $\phi \in \mathrm{Aut}(\operatorname{k}^{\rm M}_1(K))$ be given and consider $\phi^* \in \mathrm{Aut}(\mathcal{G}_K^a)$ the Kummer-dual of $\phi$.
    Then one has $\phi \in \mathrm{Aut}^{\rm M}(\operatorname{k}^{\rm M}_1(K))$ if and only if $\phi^* \in \mathrm{Aut}^{\rm c}(\mathcal{G}_K^a)$.
    \item The canonical isomorphism $\mathcal{K} : \mathrm{Aut}(\mathcal{G}_K^a) \xrightarrow{\cong} \mathrm{Aut}(\operatorname{k}^{\rm M}_1(K))$ restricts to an isomorphism $\mathcal{K} : \mathrm{Aut}^{\rm c}(\mathcal{G}_K^a) \xrightarrow{\cong} \mathrm{Aut}^{\rm M}(\operatorname{k}^{\rm M}_1(K))$.
    \item The canonical isomorphism $\mathcal{K} : \underline{\mathrm{Aut}}(\mathcal{G}_K^a) \xrightarrow{\cong} \underline{\mathrm{Aut}}(\operatorname{k}^{\rm M}_1(K))$ restricts to an isomorphism $\mathcal{K} : \underline{\mathrm{Aut}}^{\rm c}(\mathcal{G}_K^a) \xrightarrow{\cong} \underline{\mathrm{Aut}}^{\rm M}(\operatorname{k}^{\rm M}_1(K))$ which is compatible with $\rho_{k_0}$.
  \end{enumerate}

\label{fact: cohom / kummer / generalities-kummer}
  The following hold:
  \begin{enumerate}
    \item The Bockstein morphism $\beta : \operatorname{H}^1(\mathrm{Gal}_K) \rightarrow \operatorname{H}^2(\mathrm{Gal}_K)$ is trivial.
    \item The inflation map $\operatorname{H}^*(\mathcal{G}_K) \rightarrow \operatorname{H}^*(\mathrm{Gal}_K)$ is an isomorphism for $* = 0,1,2$.
  \end{enumerate}

we say that $\phi$ is {\bf compatible with C-pairs} if, for all $\sigma,\tau \in \mathfrak{g}(F_1)$, the following are equivalent
\begin{enumerate}
  \item $\sigma,\tau$ forms a C-pair in $\mathfrak{g}(F_1)$.

\label{fact: localthy / c-pairs / c-vs-cl}
  Let $F$ be a field such that $\mathrm{Char} F \neq \ell$ and $\mu_{2\ell} \subset F$, and identify $\mathfrak{g}(F)$ with $\mathcal{G}_F^a$ via some isomorphism $\mu_\ell \cong \mathbb{Z}/\ell$, as above.
  Let $\sigma,\tau \in \mathfrak{g}(F) = \mathcal{G}_F^a$ be given.
  Then the following are equivalent:
  \begin{enumerate}
    \item $\sigma,\tau$ form a C-pair.
    \item One has $[\sigma,\tau] = 0$.
  \end{enumerate}
  In particular, if $\phi$ is an element of $\mathrm{Aut}^{\rm c}(\mathcal{G}_F^a)$, then $\phi$ is compatible with C-pairs.

\label{fact: localthy / mindec / mindec}
  Let $(F,v)$ be a valued field, and let $w$ be a valuation of $Fv$.
  Then the following hold:
  \begin{enumerate}
    \item The canonical map $\sigma \mapsto \sigma_v : \mathrm{D}_v \rightarrow \mathfrak{g}(Fv)$ induces an isomorphism $\mathrm{D}_v/\mathrm{I}_v \cong \mathfrak{g}(Fv)$.
    \item One has $\mathrm{I}_v \subset \mathrm{I}_{w \circ v} \subset \mathrm{D}_{w \circ v} \subset \mathrm{D}_v$.
    \item Identifying $\mathrm{D}_v/\mathrm{I}_v$ with $\mathfrak{g}(Fv)$ as in (1), one has $\mathrm{D}_{w \circ v}/\mathrm{I}_v = \mathrm{D}_w$ and $\mathrm{I}_{w \circ v}/\mathrm{I}_v = \mathrm{I}_w$.
  \end{enumerate}

\label{fact: localthy / mindec / c-pair-mindec}
  Let $(F,v)$ be a valued field and let $\sigma,\tau \in \mathrm{D}_v$ be given such that $\sigma(-1)=\tau(-1) = 0$.
  Then the following are equivalent
  \begin{enumerate}
    \item $\sigma,\tau$ form a C-pair in $\mathfrak{g}(F)$.
    \item $\sigma_v,\tau_v$ form a C-pair in $\mathfrak{g}(Fv)$.
  \end{enumerate}

\label{theorem: localthy / qpd / main-qpd}
  Let $\sigma \in \mathrm{Aut}^{\rm M}(\operatorname{k}^{\rm M}_1(K))$ be given.
  Then the following hold:
  \begin{enumerate}
    \item Let $v$ be an $r$-quasi-divisorial valuation of $K|k$, with $r < tr.deg(K|k)$.
    Then there exists a unique $r$-quasi-divisorial valuation $v^\sigma$ of $K|k$ such that
    \[ \sigma\mathfrak{U}_v = \mathfrak{U}_{v^\sigma}, \ \ \sigma\mathfrak{U}_v^1 = \mathfrak{U}_{v^\sigma}^1. \]
    \item Let $v$ be an $r$-quasi-divisorial valuation of $K|k$ and $w$ an $s$-quasi-divisorial valuation of $K|k$, with $r,s < tr.deg(K|k)$, and let $v^\sigma,w^\sigma$ be as in (1) above.
    Then $v$ is a coarsening of $w$ if and only if $v^\sigma$ is a coarsening of $w^\sigma$.
  \end{enumerate}

\label{proposition: localthy / pd / pd-detection}
  Let $v$ be an $r$-quasi-divisorial valuation of $K|k$, with $r < tr.deg(K|k)$.
  Then the following are equivalent:
  \begin{enumerate}
    \item The valuation $v$ is an $r$-divisorial valuation of $K|k$.
    \item There exists some $t \in K_0 \smallsetminus k_0$ such that the intersection $\mathfrak{K}(t) \cap \mathfrak{U}_v^1$ is finite.
  \end{enumerate}

\label{fact: milnorff / milnordim / geometric-dim}
  Let $S$ be a subset of $K$.
  Then one has $\dim^{\rm M}(\mathfrak{K}(S)) = tr.deg(\mathbb{K}(S)|k)$.

\label{proposition: lattice / mod-ell / mod-ell-lattice}
  The following hold:
  \begin{enumerate}
    \item The set $\mathfrak{G}^*(K|k)$, endowed with the ordering by inclusion in $\operatorname{k}^{\rm M}_1(K)$ and the grading by $\dim^{\rm M}$, is a graded lattice.
    \item The map $\mathbb{K}(S) \mapsto \mathfrak{K}(S)$ induces a canonical isomorphism of graded lattices $\mathbb{G}^*(K|k) \rightarrow \mathfrak{G}^*(K|k)$.
    \item For a collection $(\mathfrak{K}_i)_i$ of elements of $\mathfrak{G}^*(K|k)$, the least-upper-bound of $(\mathfrak{K}_i)_i$ in the lattice $\mathfrak{G}^*(K|k)$ is precisely the Milnor-supremum ${\sup}^{\rm M}(\bigcup_i \mathfrak{K}_i)$.
  \end{enumerate}

