\label{fact: essram / essential-branch-locus / essential-branch-fact}
  Suppose that $X$ is a regular $k$-variety and that $K$ is a finite extension of $k(X)$.
  Let $K'$ denote the maximal separable subextension of $K|k(X)$, and let $Y$ denote the normalization of $X$ in $K'$.
  Let $x$ be a regular point of $X$ which is essentially unramified in $K$.
  Let $(f_1,\ldots,f_r)$ be a system of regular parameters at $x$ with associated flag $\mathbf{v}$ of divisorial valuations, and let $y$ be any point of $Y$ in the fiber above $x$.
  Then the following hold:
  \begin{enumerate}
    \item The system $(f_1,\ldots,f_r)$ is a system of regular parameters at $y$.
    \item Any prolongation $\mathbf{w}$ to $K$ of the flag of divisorial valuations of $k(Y) = K'$ associated to $(f_1,\ldots,f_r)$, considered as a system of regular parameters at $y$, is an $\ell$-unramified prolongation of $\mathbf{v}$.
  \end{enumerate}

\label{lemma: essram / mod-ell-divs / fibers}
  Let $t \in K \smallsetminus k$ be given and let $S$ be the unique proper normal model of $\mathbb{K}(t)|k$.
  Let $v \in \mathscr{D}_t$ be given, and let $s \in S$ be the (unique) center of $v$.
  Assume that there exists a regular $k$-variety $X$ and a smooth dominant morphism $X \rightarrow S$ with geometrically integral fibers, such that the following hold:
  \begin{enumerate}
    \item $K$ is a finite extension of $k(X)$.
    \item $s$ is in the image of $X \rightarrow S$.
    \item The fiber $X_s$ of $X \rightarrow S$ over $s$ is essentially unramified in $K$.
  \end{enumerate}
  Then there exists some $\mathfrak{V} \in \mathfrak{D}_t$ such that $\mathfrak{V} = \{{\rm U}_v\}_K$, i.e. $v$ is in the image of the canonical injective map $\mathfrak{D}_t \hookrightarrow \mathscr{D}_t$ from Lemma \ref{lemma: essram / mod-ell-divs / mod-ell-div-injection}.

\label{lemma: strgen / general / gen-birat-bertini}
  Let $F$ be an infinite field, and let $L$ be a regular function field over $F$.
  Let $x,y \in L$ be algebraically independent over $F$ with $y$ separable in $L|F$.
  Then the following hold:
  \begin{enumerate}
    \item For all but finitely many $a \in F$, the element $x+ay$ is general in $L|F$.
    \item There exists a non-empty open subset $U$ of $\mathbb{A}^2_F$ such that for all $(a,b) \in U(F)$, the element $(x-a)/(y-b)$ is general in $L|F$.
  \end{enumerate}

We say that $t$ is a {\bf strongly-general element} in $K|k$ if the following two conditions hold:
\begin{enumerate}
  \item The element $t$ is general in $K|k$.

\label{proposition: strgen / strgen / strgen-birat-bertini}
  Let $x,y \in K$ be algebraically independent over $k$ such that $y$ is separable in $K|k$.
  Then there exists a non-empty open subset $U$ of $\mathbb{A}^2_k$ such that, for all $(a,b) \in U(k)$, the element $(x-a)/(y-b)$ is strongly-general in $K|k$.

