    \item Let $x_1,\ldots,x_r \in \operatorname{k}^{\rm M}_1(K)$ be given.
    Then one has $\{x_1,\ldots,x_r\}_K = 0$ if and only if one has $\{\tau x_1,\ldots,\tau x_r\}_K = 0$.
    \item For all $t \in K_0 \smallsetminus k_0$, one has $\tau \{t\}_K \in \langle \{t\}_K,\{t-a_1\}_K,\ldots,\{t-a_r\}_K \rangle$.
  \end{enumerate}

\label{lemma: mainproof / K0 / divs-local-thy}
  Let $(v_1,\ldots,v_r)$ be a flag of divisorial valuations of $K|k$, with $r < tr.deg(K|k)$.
