\label{lemma: mainproof / K0 / fix-K0-strgen-divs}
  Let $t \in K_0 \smallsetminus k_0$ be strongly general in $K|k$, and let $c \in \mathbb{P}^1(k_0)$ be given.
  Then one has $\tau\mathfrak{V}[t;c] = \mathfrak{V}[t;c]$.

\label{proposition: mainproof / K0 / fix-K0}
  Assume that $tr.deg(K|k) \geq 2$.
  Then there exists a unique $\epsilon \in (\mathbb{Z}/\ell)^\times$ such that the following hold:
  \begin{enumerate}
    \item For all $t \in K_0^\times$, one has $\tau\{t\}_K = \epsilon \cdot \{t\}_K$.
    \item For all $t \in K_0$ which is strongly general in $K|k$ and for all $b \in k$, there exists a unique $c \in k$ such that $\tau\{t-b\}_K = \epsilon \cdot \{t-c\}_K$.
  \end{enumerate}

\[
  \xymatrix{
    \mathfrak{K}(t) \ar[d]_\tau \ar@{->>}[r] & \mathfrak{K}(t)/\mathfrak{V} \ar[d]_\tau \ar[r]^-{\Psi_{\mathfrak{V}}} & \mathbb{Z}/\ell \ar@{=}[d] \\
    \mathfrak{K}(t) \ar@{->>}[r] & \mathfrak{K}(t)/\tau\mathfrak{V} \ar[r]_-{\Psi^\tau_{\tau\mathfrak{V}}} & \mathbb{Z}/\ell.
  }
  \]

\begin{align*}
    \mathrm{div}_{\Psi}(\tau\{t-b\}_K) = \mathrm{div}_{\Psi^\tau}(\{t-b\}_K) &= \epsilon \cdot [\tau\mathfrak{V}[t;b]] - \epsilon \cdot [\tau\mathfrak{V}[t;\infty]] \\
                  &= \epsilon \cdot [\mathfrak{V}[t;c]] - \epsilon \cdot [\mathfrak{V}[t;\infty]] \\
                  &= \mathrm{div}_\Psi(\epsilon \cdot \{t-c\}_K).
  \end{align*}

\label{proposition: mainproof / K0 / independence-proposition}
  Let $x,y \in K_0$ be two elements which are algebraically independent over $k$.
  Let $e,f \in k_0$ be such that $t_e := (x-e)/y$ and $t_f := (x-f)/y$ are strongly-general in $K|k$, and let $b \in k$ be given.
  Assume that there exists a regular $k$-variety $X$ and a dominant smooth morphism $X \rightarrow \mathbb{P}^2_{x,y}$ with geometrically integral fibers, such that the following hold:
  \begin{enumerate}
    \item The closed point $(0:b:1) \in \mathbb{P}^2_{x,y}$ is in the image of $X \rightarrow \mathbb{P}^2_{x,y}$.
    \item $K$ is a finite extension of $k(X)$.
    \item The fiber of $X \rightarrow \mathbb{P}^2_{x,y}$ over $(0:b:1)$ is essentially unramified in $K$.
  \end{enumerate}
  Then there exists a unique $c \in k$ such that $\sigma\{t_e-b\}_K = \{t_e-c\}_K$ and $\sigma\{t_f-b\}_K = \{t_f-c\}_K$.

\label{lemma: mainproof / intersections / geometric-criterion}
  Let $\mathfrak{K}$ be a subgroup of $\operatorname{k}^{\rm M}_1(K)$ which is maximal among the subgroups $\Delta$ of $\operatorname{k}^{\rm M}_1(K)$ such that $\dim^{\rm M}(\Delta) = 1$.
  Assume furthermore that there exist elements of $\mathfrak{G}^*(K|k)$ denoted as follows
  \begin{itemize}
    \item $A \in \mathfrak{G}^1(K|k)$
    \item $B_1,B_2,C \in \mathfrak{G}^2(K|k)$
    \item $B_1',B_2',D \in \mathfrak{G}^3(K|k)$
  \end{itemize}
  such that the following conditions hold:
  \begin{enumerate}
    \item $B_1 \cup B_2 \subset D$, $B_1 \neq B_2$, and $A \not\subset D$.
    \item $B_1 \cup A \subset B_1'$ and $B_2 \cup A \subset B_2'$.
    \item $C \subset B_1' \cap B_2'$ and $\mathfrak{K} = B_1 \cap B_2$.
  \end{enumerate}
  Then $\mathfrak{K}$ is a one-dimensional geometric subgroup of $\operatorname{k}^{\rm M}_1(K)$, i.e. one has $\mathfrak{K} \in \mathfrak{G}^1(K|k)$.

\label{lemma: mainproof / base-case / main-base-case}
